{
  "title": "Tính bán kính và diện tích đường tròn thiết diện của hình trụ",
  "description": "Bài toán này minh họa cách một mặt phẳng vuông góc với trục của hình trụ sẽ cắt hình trụ theo một đường tròn có bán kính bằng bán kính đáy.",
  "memory_declarations": [
    {
      "name": "I",
      "type": "point3",
      "at": [0, 0, 0],
      "model_assumption": "Tâm đáy dưới của hình trụ đặt tại gốc tọa độ."
    },
    {
      "name": "J",
      "type": "point3",
      "at": [0, 0, 20],
      "model_assumption": "Tâm đáy trên của hình trụ đặt trên trục Z, cách gốc 20 đơn vị (đường cao)."
    },
    {
      "name": "P",
      "type": "point3",
      "at": [12, 0, 0],
      "model_assumption": "Một điểm trên đường tròn đáy dưới, cách tâm I 12 đơn vị (bán kính đáy)."
    },
    {
      "name": "hinh_tru",
      "type": "curved_solid",
      "source_fact_id": "hinh_tru"
    },
    {
      "name": "M",
      "type": "point3",
      "source_fact_id": "m_trung_diem_ij"
    },
    {
      "name": "line_IJ",
      "type": "line3"
    },
    {
      "name": "alpha",
      "type": "plane3",
      "source_fact_id": "mat_phang_qua_m_vuong_goc_ij"
    },
    {
      "name": "omega",
      "type": "section",
      "source_fact_id": "mat_phang_qua_m_vuong_goc_ij"
    },
    {
      "name": "ban_kinh_omega",
      "type": "float",
      "source_fact_id": "mat_phang_qua_m_vuong_goc_ij"
    },
    {
      "name": "dien_tich_omega",
      "type": "float",
      "source_fact_id": "mat_phang_qua_m_vuong_goc_ij"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "I",
      "at": [0, 0, 0],
      "label": "Tâm đáy dưới I"
    },
    {
      "kind": "declare_point",
      "target_var": "J",
      "at": [0, 0, 20],
      "label": "Tâm đáy trên J"
    },
    {
      "kind": "declare_point",
      "target_var": "P",
      "at": [12, 0, 0],
      "label": "Điểm P trên đường tròn đáy tâm I"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_tru",
      "curved_kind": "cylinder",
      "anchor": "I",
      "apex_or_top": "J",
      "rim_point": "P",
      "label": "Hình trụ"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "I",
        "b": "J"
      },
      "label": "Trung điểm M của IJ"
    },
    {
      "kind": "construct_line",
      "target_var": "line_IJ",
      "through_a": "I",
      "through_b": "J",
      "label": "Đường thẳng IJ (trục hình trụ)"
    },
    {
      "kind": "assign",
      "target_var": "alpha",
      "expr": {
        "kind": "plane_perpendicular_to_line",
        "point": "M",
        "line": "line_IJ"
      },
      "label": "Mặt phẳng alpha đi qua M và vuông góc với IJ"
    },
    {
      "kind": "construct_section",
      "target_var": "omega",
      "solid": "hinh_tru",
      "plane": "alpha",
      "label": "Đường tròn (ω) là thiết diện của hình trụ với mặt phẳng alpha"
    },
    {
      "kind": "assign",
      "target_var": "ban_kinh_omega",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "omega"
      },
      "label": "Bán kính của đường tròn (ω)"
    },
    {
      "kind": "assign",
      "target_var": "dien_tich_omega",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "omega"
      },
      "label": "Diện tích của đường tròn (ω)"
    }
  ],
  "pedagogical_intent": "Chương trình này cho thấy cách dựng một hình trụ, xác định trung điểm của trục, và tạo một mặt phẳng cắt vuông góc với trục để tìm thiết diện là một đường tròn."
}

